import{_ as t,o,c as d,a2 as i}from"./chunks/framework.BfI5QxtK.js";const g=JSON.parse('{"title":"gnoblin.configure.shell","description":"","frontmatter":{},"headers":[],"relativePath":"config/configure/shell.md","filePath":"config/configure/shell.md"}'),n={name:"config/configure/shell.md"};function c(a,e,r,s,l,u){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="gnoblin-configure-shell" tabindex="-1">gnoblin.configure.shell <a class="header-anchor" href="#gnoblin-configure-shell" aria-label="Permalink to &quot;gnoblin.configure.shell&quot;">​</a></h1><p>Configure this part of <code>gnoblin.configure</code> with the <code>shell</code> key.</p><p>Put these fields inside <code>gnoblin.configure {shell = {...}}</code>. Changes apply on configuration reload unless the row says the preference is persisted.</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Default</th></tr></thead><tbody><tr><td><code>minimize_animation</code></td><td><code>&quot;zoom&quot;</code>, <code>&quot;fade&quot;</code>, <code>&quot;none&quot;</code>, <code>&quot;gnome&quot;</code></td><td><code>&quot;zoom&quot;</code></td></tr><tr><td><code>minimize_duration</code></td><td>0–5000 ms</td><td><code>200</code></td></tr><tr><td><code>minimize_target</code></td><td><code>{x, y}</code> in desktop logical pixels</td><td>Dock target, then bottom centre</td></tr><tr><td><code>layer_animation</code></td><td><code>&quot;slide&quot;</code>, <code>&quot;fade&quot;</code>, <code>&quot;none&quot;</code></td><td><code>&quot;slide&quot;</code></td></tr><tr><td><code>layer_duration</code></td><td>0–5000 ms</td><td><code>220</code></td></tr><tr><td><code>layer_easing</code></td><td><code>&quot;linear&quot;</code>, <code>&quot;ease-out-quad&quot;</code>, <code>&quot;ease-out-cubic&quot;</code>, <code>&quot;ease-in-out-cubic&quot;</code></td><td><code>&quot;ease-out-cubic&quot;</code></td></tr><tr><td><code>window_menu</code></td><td>Command argument list</td><td>Empty</td></tr><tr><td><code>window_switcher</code></td><td>Boolean</td><td><code>false</code></td></tr><tr><td><code>notifications</code></td><td>Boolean</td><td>Initially disabled; persists in GSettings</td></tr><tr><td><code>input_source_switcher</code></td><td>Boolean</td><td>Initially disabled; persists in GSettings</td></tr><tr><td><code>wallpaper</code></td><td>Boolean</td><td><code>true</code>; persists in GSettings</td></tr></tbody></table><p><code>minimize_animation</code> and <code>layer_animation</code> select a built-in name or a map of event names to custom animation names. Their accepted values and motion are described in the <a href="/gnoblin/guides/animations">animation guide</a>. <code>minimize_target</code> is a two-number <code>{x, y}</code> position in logical desktop pixels; omitted coordinates use the dock target or bottom-center fallback.</p><p>Notification and input-source preferences persist in GSettings. With no usable picture configured, GNOME displays its configured background color.</p><p>Guides: <a href="/gnoblin/guides/animations">animations</a>, <a href="/gnoblin/guides/session_settings">native features</a>, <a href="/gnoblin/guides/window_menu">window menu</a>.</p>',7)])])}const p=t(n,[["render",c]]);export{g as __pageData,p as default};
